        // Set AFTER the hash above, so it can never enter the content fingerprint.
        'ingest_ts': System.currentTimeMillis().toString(),
        'dedupe.key': dedupeKey,
        // Stable object identity (no content hash) sent downstream as a header/value field.
        // Deliberately NOT dedupeKey -- that keeps the hash and stays internal-only.
        // The hash remains available downstream as payload_hash_fingerprint.
